// Hero scenes v3 — richer monochrome illustrations. Spliced into mono-kit.js between `const H = {};` and the medals section.
// Tones: INK focal · MID mid-distance · DIM far/texture/surfaces · GROUND cut-outs. Stage 393×240, horizon y=190, centre x=196.
  const MID = '#8E8A82', DIM = '#3A3835', DIM2 = '#262523';
  const HTOP = {};
