  const tuft = (x, y, c = INK, s = 1) => `<path d="M${x} ${y} l${-3 * s} ${-8 * s} M${x} ${y} v${-11 * s} M${x} ${y} l${3 * s} ${-8 * s}" fill="none" stroke="${c}" stroke-width="${1.6 * s}" stroke-linecap="round"></path>`;
