  const ground = (o = {}) => `${lens(28, 364, 190, 8)}${tuft(o.tl ?? 72, 190)}${tuft(o.tr ?? 322, 190)}${pebble(o.pl ?? 108, 196, 4)}${pebble(o.pr ?? 286, 197, 3)}`;
