  const stars = (pts, c = INK) => pts.map(p => star(p[0], p[1], p[2] || 3.2, c)).join('');
  const moon = (cx, cy, r, ink = INK, bg = GROUND) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${ink}"></circle><circle cx="${cx + r * 0.42}" cy="${cy - r * 0.32}" r="${r * 0.82}" fill="${bg}"></circle>`;
  const cloud = (x, y, s = 1, c = DIM) => `<g fill="${c}"><circle cx="${x}" cy="${y}" r="${9 * s}"></circle><circle cx="${x + 12 * s}" cy="${y - 5 * s}" r="${12 * s}"></circle><circle cx="${x + 26 * s}" cy="${y}" r="${9 * s}"></circle><rect x="${x - 2 * s}" y="${y}" width="${30 * s}" height="${9 * s}" rx="${4.5 * s}"></rect></g>`;
  const birds = (pts, c = MID) => pts.map(([x, y, s = 1]) => `<path d="M${x - 7 * s} ${y} q${3.5 * s} ${-4 * s} ${7 * s} 0 q${3.5 * s} ${-4 * s} ${7 * s} 0" fill="none" stroke="${c}" stroke-width="${1.7 * s}" stroke-linecap="round"></path>`).join('');
